	s := PersistentSnapshot{
		Users:                    make(map[string]*User),
		Sessions:                 make(map[string]*Session),
		SampleTypes:              make(map[string]*SampleType),
		Locations:                make(map[string]*Location),
		Connections:              make(map[string]*Connection),
		LabAcceptances:           make(map[string]map[string]string),
		Samples:                  make(map[string]*Sample),
		Journeys:                 make(map[string]*JourneyPlan),
		Assignments:              make(map[string]*Assignment),
		Handoffs:                 make(map[string]*Handoff),
		Idempotency:              make(map[string]*IdempotencyRecord),
		AuditEntries:             []AuditEntry{},
		RealtimeEvents:           []RealtimeEvent{},
		NextEventID:              1,
		NextAuditSeq:             1,
		NextRealtimeID:           1,
		NextOfferSeq:             1,
		NetworkRevision:          0,
		ServiceabilityVersionSeq: 1,
		ServiceabilitySnapshot: ServiceabilitySnapshot{
			Version:                    1,
			Status:                     "complete",
			ComputedAt:                 now,
			NetworkRevision:            0,
			Regions:                    []ServiceabilityRegion{},
			ActiveCollectionPointCount: 0,
		},
	}
	seedDefaultSampleTypes(&s)
	return s
}

