func (s *Store) getLocationCapacityLocked(loc *Location) Capacity {
	capUnits := loc.Capacity.CapacityUnits
	cooledUnits := loc.Capacity.CooledCapacityUnits
	if !loc.CapacityConfigured {
		capUnits = DefaultNodeCapacity
		cooledUnits = DefaultNodeCapacity
	}
	avail := capUnits - loc.Capacity.ReservedUnits
	if avail < 0 {
		avail = 0
	}
	cooledAvail := cooledUnits - loc.Capacity.CooledReservedUnits
	if cooledAvail < 0 {
		cooledAvail = 0
	}
	return Capacity{
		CapacityUnits:        capUnits,
		ReservedUnits:        loc.Capacity.ReservedUnits,
		AvailableUnits:       avail,
		CooledCapacityUnits:  cooledUnits,
		CooledReservedUnits:  loc.Capacity.CooledReservedUnits,
		CooledAvailableUnits: cooledAvail,
	}
}

func (s *Store) getConnectionCapacityLocked(conn *Connection) Capacity {
	capUnits := conn.Capacity.CapacityUnits
	cooledUnits := conn.Capacity.CooledCapacityUnits
	if !conn.CapacityConfigured {
		capUnits = DefaultConnCapacity
		if conn.Cooled {
			cooledUnits = DefaultConnCapacity
		} else {
			cooledUnits = 0
		}
	}
	avail := capUnits - conn.Capacity.ReservedUnits
	if avail < 0 {
		avail = 0
	}
	cooledAvail := cooledUnits - conn.Capacity.CooledReservedUnits
	if cooledAvail < 0 {
		cooledAvail = 0
	}
	return Capacity{
		CapacityUnits:        capUnits,
		ReservedUnits:        conn.Capacity.ReservedUnits,
		AvailableUnits:       avail,
		CooledCapacityUnits:  cooledUnits,
		CooledReservedUnits:  conn.Capacity.CooledReservedUnits,
		CooledAvailableUnits: cooledAvail,
	}
}

func (s *Store) recomputeServiceabilityLocked(bumpRevision bool) {
	if bumpRevision {
		s.state.NetworkRevision++
		s.state.ServiceabilityVersionSeq++
	}
	if s.state.ServiceabilityVersionSeq < 1 {
		s.state.ServiceabilityVersionSeq = 1
	}
	regions := []ServiceabilityRegion{}
	locIDs := make([]string, 0, len(s.state.Locations))
	for id := range s.state.Locations {
		locIDs = append(locIDs, id)
	}
	sort.Strings(locIDs)
	for _, id := range locIDs {
		loc := s.state.Locations[id]
		if loc.Active && loc.Functions.CollectionPoint {
			regions = append(regions, ServiceabilityRegion{
				LocationID: loc.LocationID,
				Name:       loc.Name,
				Latitude:   loc.Coordinate.Latitude,
				Longitude:  loc.Coordinate.Longitude,
				CoverageKm: loc.CoverageKm,
			})
		}
	}
	s.state.ServiceabilitySnapshot = ServiceabilitySnapshot{
		Version:                    s.state.ServiceabilityVersionSeq,
		Status:                     "complete",
		ComputedAt:                 time.Now().UTC().Format(time.RFC3339),
		NetworkRevision:            s.state.NetworkRevision,
		Regions:                    regions,
		ActiveCollectionPointCount: len(regions),
	}
}

