func (srv *Server) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		JourneyID           *string `json:"journeyId"`
		ExpectedPlanVersion *int    `json:"expectedPlanVersion"`
		Reason              string  `json:"reason"`
		IdempotencyKey      *string `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.JourneyID == nil || req.ExpectedPlanVersion == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "cancel_journey", "journey", *req.JourneyID, true, "administrator", "dispatcher")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if *req.ExpectedPlanVersion < 1 {
		writeError(w, http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("cancel_journey", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	jp := srv.store.state.Journeys[*req.JourneyID]
	if jp == nil {
		writeError(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if jp.PlanVersion != *req.ExpectedPlanVersion {
		writeError(w, http.StatusConflict, "stale_plan", "journey planVersion does not match expectedPlanVersion")
		return
	}
	if jp.Status == "cancelled" || jp.Status == "completed" || jp.Status == "replaced" {
		writeError(w, http.StatusConflict, "inactive_plan", "journey is already inactive")
		return
	}

	nowStr := time.Now().UTC().Format(time.RFC3339)
	_, _ = srv.store.cancelUnfinishedAssignmentsLocked(jp)
	srv.store.releaseJourneyCapacityLocked(jp)
	jp.Status = "cancelled"
	jp.PlanVersion++

	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "cancel_journey", "journey", jp.JourneyID, true, nowStr, map[string]any{
		"reason": req.Reason,
	})
	jp.History = append(jp.History, tl)

	for _, sid := range jp.SampleIDs {
		if smp := srv.store.state.Samples[sid]; smp != nil && smp.Status != "received" {
			smp.Status = "cancelled"
			smp.Timeline = append(smp.Timeline, tl)
		}
	}

	srv.store.recomputeServiceabilityLocked(false)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "cancel_journey", "journey", jp.JourneyID, true, map[string]any{
		"sampleIds": jp.SampleIDs,
		"reason":    req.Reason,
	})
	srv.store.publishRealtimeLocked("journey.cancelled", "journey", jp.JourneyID, map[string]any{
		"journeyId": jp.JourneyID,
		"status":    "cancelled",
	})

	respData := map[string]any{
		"journeyId": jp.JourneyID,
		"status":    "cancelled",
		"sampleIds": jp.SampleIDs,
	}
	srv.saveIdempotencyLocked("cancel_journey", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

