	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.ResourceType == nil || req.ResourceID == nil || req.OccurredAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "report_disruption", "disruption", *req.ResourceID, true, "administrator", "dispatcher")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("report_disruption", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	if _, ok := parseTimeRFC3339(*req.OccurredAt); !ok {
		writeError(w, http.StatusBadRequest, "invalid_time", "invalid occurredAt")
		return
	}

	resType := strings.TrimSpace(*req.ResourceType)
	resID := strings.TrimSpace(*req.ResourceID)
	switch resType {
	case "location", "node", "laboratory":
		loc := srv.store.state.Locations[resID]
		if loc == nil {
			writeError(w, http.StatusNotFound, "not_found", "location not found")
			return
		}
		if resType == "laboratory" {
			loc.Functions.Laboratory = false
		} else {
			loc.Active = false
		}
	case "connection", "route":
		conn := srv.store.state.Connections[resID]
		if conn == nil {
			writeError(w, http.StatusNotFound, "not_found", "connection not found")
			return
		}
		conn.Active = false
	case "worker":
		u := srv.store.state.Users[resID]
		if u == nil {
			writeError(w, http.StatusNotFound, "not_found", "worker not found")
			return
		}
		u.Available = false
	case "capacity":
		if loc := srv.store.state.Locations[resID]; loc != nil {
			loc.CapacityConfigured = true
			loc.Capacity.CapacityUnits = loc.Capacity.ReservedUnits
			loc.Capacity.CooledCapacityUnits = loc.Capacity.CooledReservedUnits
		} else if conn := srv.store.state.Connections[resID]; conn != nil {
			conn.CapacityConfigured = true
			conn.Capacity.CapacityUnits = conn.Capacity.ReservedUnits
			conn.Capacity.CooledCapacityUnits = conn.Capacity.CooledReservedUnits
		} else {
			writeError(w, http.StatusNotFound, "not_found", "capacity resource not found")
			return
		}
	default:
		writeError(w, http.StatusBadRequest, "invalid_resource_type", "invalid resourceType")
		return
	}

	affectedSamples := []string{}
	replacementPlans := []string{}
	overallStatus := "not_required"

	jIDs := make([]string, 0, len(srv.store.state.Journeys))
	for id := range srv.store.state.Journeys {
		jIDs = append(jIDs, id)
	}
	sort.Strings(jIDs)

	for _, jid := range jIDs {
		jp := srv.store.state.Journeys[jid]
		if jp == nil || jp.Status == "cancelled" || jp.Status == "completed" || jp.Status == "replaced" {
			continue
		}
		affected := false
		switch resType {
		case "location", "node", "laboratory", "capacity":
			for _, leg := range jp.Legs {
				a := srv.store.state.Assignments[leg.AssignmentID]
				if a != nil && !isAssignmentCompleted(a.Status) {
					if leg.FromLocationID == resID || leg.ToLocationID == resID {
						affected = true
						break
					}
				}
			}
			for _, st := range jp.OrderedStops {
				if st.CompletedAt == "" && st.LocationID == resID {
					affected = true
					break
				}
			}
		case "connection", "route":
			for _, leg := range jp.Legs {
				a := srv.store.state.Assignments[leg.AssignmentID]
				if a != nil && !isAssignmentCompleted(a.Status) && leg.ConnectionID == resID {
					affected = true
					break
				}
			}
		case "worker":
			for _, aid := range append(append(append([]string{}, jp.CollectionAssignmentIDs...), jp.NodeAssignmentIDs...), jp.LaboratoryAssignmentIDs...) {
				if a := srv.store.state.Assignments[aid]; a != nil && !isAssignmentCompleted(a.Status) && (a.WorkerID == resID || a.OfferedToWorkerID == resID) {
					affected = true
					break
				}
			}
			for _, leg := range jp.Legs {
				if a := srv.store.state.Assignments[leg.AssignmentID]; a != nil && !isAssignmentCompleted(a.Status) && (a.WorkerID == resID || a.OfferedToWorkerID == resID) {
					affected = true
					break
				}
			}
		}

		if !affected {
			continue
		}

		for _, sid := range jp.SampleIDs {
			smp := srv.store.state.Samples[sid]
			if smp == nil || smp.Status == "received" || smp.Status == "cancelled" {
				continue
			}
			affectedSamples = append(affectedSamples, sid)
			st, newJP := srv.store.replanSampleJourneyLocked(smp, jp, ac.user.UserID, ac.role, req.Reason)
			if newJP != nil {
				replacementPlans = append(replacementPlans, newJP.JourneyID)
			}
			if st == "expired" {
				overallStatus = "expired"
			} else if st == "exception" && overallStatus != "expired" {
				overallStatus = "exception"
			} else if st == "replaced" && overallStatus == "not_required" {
				overallStatus = "replaced"
			}
		}
	}

	disruptionID := NewUUID()
	srv.store.recomputeServiceabilityLocked(true)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "report_disruption", resType, resID, true, map[string]any{
		"disruptionId":      disruptionID,
		"affectedSampleIds": affectedSamples,
		"replanStatus":      overallStatus,
	})
	srv.store.publishRealtimeLocked("disruption.reported", "disruption", disruptionID, map[string]any{
		"disruptionId":      disruptionID,
		"resourceType":      resType,
		"resourceId":        resID,
		"affectedSampleIds": affectedSamples,
		"replanStatus":      overallStatus,
	})

	respData := map[string]any{
		"disruptionId":       disruptionID,
		"affectedSampleIds":  affectedSamples,
		"replacementPlanIds": replacementPlans,
		"replanStatus":       overallStatus,
	}
	srv.saveIdempotencyLocked("report_disruption", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		TargetJourneyID     *string  `json:"targetJourneyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      *string  `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.TargetJourneyID == nil || req.ExpectedPlanVersion == nil || req.SourceJourneyIDs == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "merge_journeys", "journey", *req.TargetJourneyID, true, "administrator", "dispatcher")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if *req.ExpectedPlanVersion < 1 {
		writeError(w, http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("merge_journeys", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	if len(req.SourceJourneyIDs) == 0 {
		writeError(w, http.StatusConflict, "invalid_merge", "sourceJourneyIds cannot be empty")
		return
	}

	targetJP := srv.store.state.Journeys[*req.TargetJourneyID]
	if targetJP == nil {
		writeError(w, http.StatusNotFound, "not_found", "target journey not found")
		return
	}
	if targetJP.PlanVersion != *req.ExpectedPlanVersion {
		writeError(w, http.StatusConflict, "stale_plan", "target journey planVersion does not match expectedPlanVersion")
		return
	}
	if targetJP.Status == "cancelled" || targetJP.Status == "completed" || targetJP.Status == "replaced" {
		writeError(w, http.StatusConflict, "inactive_plan", "target journey is inactive")
		return
	}

	for _, leg := range targetJP.Legs {
		if a := srv.store.state.Assignments[leg.AssignmentID]; a != nil && (isAssignmentCompleted(a.Status) || isAssignmentInProgress(a.Status)) {
			writeError(w, http.StatusConflict, "completed_work_immutable", "cannot merge journey with in-progress or completed transport legs")
			return
		}
	}

	mergedSampleIDs := append([]string{}, targetJP.SampleIDs...)
	var sourceJPs []*JourneyPlan
	for _, srcID := range req.SourceJourneyIDs {
		if srcID == targetJP.JourneyID {
			writeError(w, http.StatusConflict, "invalid_merge", "cannot merge journey into itself")
			return
		}
		sjp := srv.store.state.Journeys[srcID]
		if sjp == nil {
			writeError(w, http.StatusNotFound, "not_found", "source journey not found")
			return
		}
		if sjp.Status == "cancelled" || sjp.Status == "completed" || sjp.Status == "replaced" {
			writeError(w, http.StatusConflict, "inactive_plan", "source journey is inactive")
			return
		}
		for _, leg := range sjp.Legs {
			if a := srv.store.state.Assignments[leg.AssignmentID]; a != nil && (isAssignmentCompleted(a.Status) || isAssignmentInProgress(a.Status)) {
				writeError(w, http.StatusConflict, "partial_journey_merge", "cannot merge source journey that already has completed or in-progress transport work")
				return
			}
		}
		sourceJPs = append(sourceJPs, sjp)
		mergedSampleIDs = append(mergedSampleIDs, sjp.SampleIDs...)
	}

	// Temporarily release source journey capacities to test if merged target journey fits
	for _, sjp := range sourceJPs {
		srv.store.releaseJourneyCapacityLocked(sjp)
	}

	origSamples := append([]string{}, targetJP.SampleIDs...)
	targetJP.SampleIDs = mergedSampleIDs

	if valErr := srv.store.recalculateStopsAndValidatePlanLocked(targetJP); valErr != nil {
		// Restore original state
		targetJP.SampleIDs = origSamples
		for _, sjp := range sourceJPs {
			needsCooled := false
			for _, sid := range sjp.SampleIDs {
				if smp := srv.store.state.Samples[sid]; smp != nil {
					if srv.store.sampleNeedsCooledLocked(srv.store.state.SampleTypes[smp.SampleTypeID]) {
						needsCooled = true
					}
				}
			}
			srv.store.reserveJourneyCapacityLocked(sjp, needsCooled, len(sjp.SampleIDs))
		}
		writeError(w, valErr.status, valErr.code, valErr.msg)
		return
	}

	// Commit merge: update capacity reservation on targetJP and cancel source journeys
	srv.store.releaseJourneyCapacityLocked(targetJP)
	needsCooled := false
	for _, sid := range targetJP.SampleIDs {
		if smp := srv.store.state.Samples[sid]; smp != nil {
			if srv.store.sampleNeedsCooledLocked(srv.store.state.SampleTypes[smp.SampleTypeID]) {
				needsCooled = true
			}
		}
	}
	srv.store.reserveJourneyCapacityLocked(targetJP, needsCooled, len(targetJP.SampleIDs))

	for _, sjp := range sourceJPs {
		_, _ = srv.store.cancelUnfinishedAssignmentsLocked(sjp)
		sjp.Status = "replaced"
		for _, sid := range sjp.SampleIDs {
			if smp := srv.store.state.Samples[sid]; smp != nil {
				smp.ActiveJourneyID = targetJP.JourneyID
			}
		}
	}

	targetJP.RouteMode = "batched"
	targetJP.PlanVersion++
	validTrue := true
	targetJP.Valid = &validTrue

	nowStr := time.Now().UTC().Format(time.RFC3339)
	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "merge_journeys", "journey", targetJP.JourneyID, true, nowStr, map[string]any{
		"sourceJourneyIds": req.SourceJourneyIDs,
		"sampleIds":        targetJP.SampleIDs,
	})
	targetJP.History = append(targetJP.History, tl)

	srv.store.recomputeServiceabilityLocked(false)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "merge_journeys", "journey", targetJP.JourneyID, true, map[string]any{
		"sourceJourneyIds": req.SourceJourneyIDs,
		"sampleIds":        targetJP.SampleIDs,
	})

	srv.saveIdempotencyLocked("merge_journeys", *req.IdempotencyKey, raw, http.StatusCreated, targetJP)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, targetJP)
}

func (srv *Server) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		JourneyID           *string  `json:"journeyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      *string  `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.JourneyID == nil || req.ExpectedPlanVersion == nil || req.SampleIDs == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "split_journey", "journey", *req.JourneyID, true, "administrator", "dispatcher")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if *req.ExpectedPlanVersion < 1 {
		writeError(w, http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("split_journey", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	jp := srv.store.state.Journeys[*req.JourneyID]
	if jp == nil {
		writeError(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if jp.PlanVersion != *req.ExpectedPlanVersion {
		writeError(w, http.StatusConflict, "stale_plan", "journey planVersion does not match expectedPlanVersion")
		return
	}
	if jp.Status == "cancelled" || jp.Status == "completed" || jp.Status == "replaced" {
		writeError(w, http.StatusConflict, "inactive_plan", "journey is inactive")
