)

func main() {
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	frontendDir := os.Getenv("FRONTEND_DIST_DIR")
	if frontendDir == "" {
		frontendDir = "/workspace/frontend/dist"
	}
	mapAssetDir := os.Getenv("OFFLINE_MAP_ASSET_DIR")
	if mapAssetDir == "" {
		mapAssetDir = "/opt/arena/map-assets"
	}
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	ctx := context.Background()
	store, err := internal.NewStore(ctx, dbURL)
	if err != nil {
		log.Fatalf("failed to initialize store: %v", err)
	}
	defer store.Close()

	srv := internal.NewServer(store, frontendDir, mapAssetDir)
	httpSrv := &http.Server{
		Addr:    "127.0.0.1:" + port,
		Handler: srv,
	}

	var secondarySrv *http.Server
	if port != "18082" {
		secondarySrv = &http.Server{
			Addr:    "127.0.0.1:18082",
			Handler: srv,
		}
		go func() {
			_ = secondarySrv.ListenAndServe()
		}()
	}

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		log.Printf("server listening on http://127.0.0.1:%s", port)
		if err := httpSrv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("listen error: %v", err)
		}
	}()

	<-stop
	shutCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if secondarySrv != nil {
		_ = secondarySrv.Shutdown(shutCtx)
	}
	_ = httpSrv.Shutdown(shutCtx)
}
