{"file_text":"import React, { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { Protocol } from 'pmtiles';

let pmtilesProtocolRegistered = false;

export interface MapViewProps {
  locations?: any[];
  workers?: any[];
  samples?: any[];
  routes?: any[];
}

export const MapView: React.FC<MapViewProps> = ({
  locations = [],
  workers = [],
  samples = [],
  routes = []
}) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);

  useEffect(() => {
    if (!pmtilesProtocolRegistered) {
      const protocol = new Protocol();
      maplibregl.addProtocol('pmtiles', protocol.tile);
      pmtilesProtocolRegistered = true;
    }

    if (!containerRef.current || mapRef.current) {
      return;
    }

    const origin = window.location.origin;
    const localStyle: any = {
      version: 8,
      name: 'Offline Bangalore Light',
      center: [77.5946, 12.9716],
      zoom: 11,
      glyphs: `${origin}/map-assets/fonts/{fontstack}/{range}.pbf`,
      sprite: `${origin}/map-assets/sprites/light`,
      sources: {
        basemap: {
          type: 'vector',
          url: `pmtiles://${origin}/map-assets/bangalore.pmtiles`,
          attribution: '© OpenStreetMap contributors'
        }
      },
      layers: [
        {
          id: 'background',
          type: 'background',
          paint: { 'background-color': '#f5f4ef' }
        },
        {
          id: 'landuse',
          type: 'fill',
          source: 'basemap',
          'source-layer': 'landuse',
          paint: { 'fill-color': '#e8eddf', 'fill-opacity': 0.7 }
        },
        {
          id: 'water',
          type: 'fill',
          source: 'basemap',
          'source-layer': 'water',
          paint: { 'fill-color': '#b9d9eb' }
        },
        {
          id: 'buildings',
          type: 'fill',
          source: 'basemap',
          'source-layer': 'buildings',
          minzoom: 12,
          paint: { 'fill-color': '#ddd5ce', 'fill-outline-color': '#c8beb6' }
        },
        {
          id: 'roads',
          type: 'line',
          source: 'basemap',
          'source-layer': 'roads',
          paint: { 'line-color': '#ffffff', 'line-width': 1.5 }
        },
        {
          id: 'boundaries',
          type: 'line',
          source: 'basemap',
          'source-layer': 'boundaries',
          paint: { 'line-color': '#8e8e8e', 'line-dasharray': [3, 2], 'line-width': 1 }
        }
      ]
    };

    try {
      const map = new maplibregl.Map({
        container: containerRef.current,
        style: localStyle,
        center: [77.5946, 12.9716],
        zoom: 11,
        attributionControl: false
      });
      mapRef.current = map;
    } catch {
      // Fallback if WebGL is unavailable in headless environment
    }

    return () => {
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;

    markersRef.current.forEach((m) => m.remove());
    markersRef.current = [];

    locations.forEach((loc) => {
      const coord = loc?.coordinate;
      if (coord && typeof coord.longitude === 'number' && typeof coord.latitude === 'number') {
        const el = document.createElement('div');
        const isLab = Boolean(loc?.functions?.laboratory);
        el.style.width = '14px';
        el.style.height = '14px';
        el.style.borderRadius = '50%';
        el.style.backgroundColor = isLab ? '#7c3aed' : '#0284c7';
        el.style.border = '2px solid #ffffff';
        el.title = `${loc.name || loc.locationId} (${isLab ? 'Laboratory' : 'Node'})`;
        const marker = new maplibregl.Marker({ element: el })
          .setLngLat([coord.longitude, coord.latitude])
          .addTo(map);
        markersRef.current.push(marker);
      }
    });

    workers.forEach((w) => {
      const coord = w?.latestLocation;
      if (coord && typeof coord.longitude === 'number' && typeof coord.latitude === 'number') {
        const el = document.createElement('div');
        el.style.width = '12px';
        el.style.height = '12px';
        el.style.borderRadius = '50%';
        el.style.backgroundColor = '#16a34a';
        el.style.border = '2px solid #ffffff';
        el.title = `Worker ${w.fullName || w.workerId}`;
        const marker = new maplibregl.Marker({ element: el })
          .setLngLat([coord.longitude, coord.latitude])
          .addTo(map);
        markersRef.current.push(marker);
      }
    });

    samples.forEach((s) => {
      const coord = s?.latestLocation || s?.origin;
      if (coord && typeof coord.longitude === 'number' && typeof coord.latitude === 'number') {
        const el = document.createElement('div');
        el.style.width = '10px';
        el.style.height = '10px';
        el.style.borderRadius = '50%';
        el.style.backgroundColor = s.status === 'exception' ? '#dc2626' : '#f59e0b';
        el.style.border = '2px solid #ffffff';
        el.title = `Sample ${s.sampleId} (${s.status})`;
        const marker = new maplibregl.Marker({ element: el })
          .setLngLat([coord.longitude, coord.latitude])
          .addTo(map);
        markersRef.current.push(marker);
      }
    });
  }, [locations, workers, samples, routes]);

  return (
    <section
      aria-label="Live Operations Map"
      style={{
        border: '1px solid #cbd5e1',
        borderRadius: '8px',
        padding: '12px',
        marginBottom: '16px',
        background: '#ffffff'
      }}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
        <h2 style={{ margin: 0, fontSize: '16px' }}>Live Network &amp; Custody Map (Offline PMTiles: Bangalore)</h2>
        <div style={{ fontSize: '12px', color: '#475569' }}>
          Nodes: {locations.length} | Active Workers: {workers.length} | Tracked Samples: {samples.length} | Routes: {routes.length}
        </div>
      </div>
      <div
        ref={containerRef}
        data-testid="maplibre-container"
        aria-label="Map Canvas"
        style={{ width: '100%', height: '260px', borderRadius: '6px', background: '#f5f4ef' }}
      />
    </section>
  );
};
