import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"testing"
	"time"
)

func doReq(t *testing.T, srv *Server, method, path, token string, body any) (int, map[string]any) {
	t.Helper()
	var buf bytes.Buffer
	if body != nil {
		if err := json.NewEncoder(&buf).Encode(body); err != nil {
			t.Fatalf("encode body: %v", err)
		}
	}
	req := httptest.NewRequest(method, path, &buf)
	req.Header.Set("Content-Type", "application/json")
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	rec := httptest.NewRecorder()
	srv.ServeHTTP(rec, req)

	var out map[string]any
	if rec.Body.Len() > 0 {
		if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
			t.Fatalf("unmarshal response (%d %s): %v; raw=%s", rec.Code, path, err, rec.Body.String())
		}
	}
	return rec.Code, out
}

func TestEndToEndSampleLifecycleAndContracts(t *testing.T) {
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	os.Setenv("ADMIN_USERNAME", "admin")
	os.Setenv("ADMIN_PASSWORD", "adminpass123")

	ctx := context.Background()
	if err := ResetDatabase(ctx, dbURL); err != nil {
		t.Fatalf("ResetDatabase: %v", err)
	}

	store, err := NewStore(ctx, dbURL)
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	defer store.Close()

	srv := NewServer(store, "/workspace/frontend/dist", "/opt/arena/map-assets")

	// 1. Check /ready
	code, readyResp := doReq(t, srv, http.MethodGet, "/ready", "", nil)
	if code != http.StatusOK || readyResp["status"] != "ready" {
		t.Fatalf("expected /ready 200 ready, got %d %v", code, readyResp)
	}

	// 2. Invalid login
	code, errResp := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]any{
		"username": "admin",
		"password": "wrong",
	})
	if code != http.StatusUnauthorized || errResp["code"] != "invalid_credentials" {
		t.Fatalf("expected 401 invalid_credentials, got %d %v", code, errResp)
	}

	// 3. Valid admin login
	code, loginResp := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]any{
		"username": "admin",
		"password": "adminpass123",
	})
	if code != http.StatusOK {
		t.Fatalf("expected 200 login, got %d %v", code, loginResp)
	}
	adminData := loginResp["data"].(map[string]any)
	adminToken := adminData["sessionToken"].(string)
	if adminData["activeRole"] != "administrator" {
		t.Fatalf("expected activeRole=administrator, got %v", adminData["activeRole"])
